pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    Recorder recorder;

    function setUp() public {
        c = new EBU();
        recorder = new Recorder();
    }

    function testFuzz_property(address from, uint256 n) public {
        n = bound(n, 0, 8);
        address[] memory tos = new address[](n);
        uint256[] memory v = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(recorder);
            v[i] = i + 1;
        }

        bool ok = false;
        try c.transfer(from, address(recorder), tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(recorder.callCount() > 0);
        } else {
            assertTrue(true);
        }
    }
}

contract Recorder {
    uint256 public callCount;

    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        return true;
    }
}
